const Slide138: Page = () => <div data-workshop-slide="revised-Slide138" style={{position:'relative',width:'100%',height:'100%',background:'var(--osd-bg)',color:'var(--osd-text)',fontFamily:'var(--osd-font-body)'}}><div data-workshop-marker style={{position:'absolute',left:0,top:0,width:1920,height:38,background:'#E9EEDD'}}><span style={{position:'absolute',left:100,top:8,fontSize:20,lineHeight:1.1,fontWeight:600,letterSpacing:1,color:'#3E635E'}}>Workshop 5 · Hands-on</span></div><h1 style={{position:'absolute',left:100,top:65,width:1720,fontSize:62,fontWeight:700,lineHeight:1.13,margin:0}}>Goals: require evidence and control continuation</h1><div style={{position:"absolute",left:100,top:265,width:1720,borderTop:"2px solid #CCC6B6",paddingTop:24}}><div style={{fontSize:28,color:"#2E70FF",fontWeight:700,width:390}}>WHAT WE OBSERVED</div><div style={{position:"absolute",left:440,top:20,fontSize:39,lineHeight:1.4,width:1250}}>A staged stop was rejected, continued, and accepted.</div></div><div style={{position:"absolute",left:100,top:470,width:1720,borderTop:"2px solid #CCC6B6",paddingTop:24}}><div style={{fontSize:28,color:"#2E70FF",fontWeight:700,width:390}}>WHAT WE CHANGE</div><div style={{position:"absolute",left:440,top:20,fontSize:39,lineHeight:1.4,width:1250}}>Make required artifacts and checks explicit.</div></div><div style={{position:"absolute",left:100,top:675,width:1720,borderTop:"2px solid #CCC6B6",paddingTop:24}}><div style={{fontSize:28,color:"#2E70FF",fontWeight:700,width:390}}>WHAT WE MEASURE</div><div style={{position:"absolute",left:440,top:20,fontSize:39,lineHeight:1.4,width:1250}}>Completion, unsupported stops, scope, and total effort.</div></div><p style={{position:'absolute',left:100,top:925,width:1650,fontSize:28,lineHeight:1.35,color:'#676358'}}>Ordinary resumption also succeeded. This is a mechanism lesson.</p><div style={{position:'absolute',right:100,bottom:30,fontSize:25,color:'#999386'}}>@rajistics</div></div>;

