const Slide165: Page = () => <div data-workshop-slide="closing-six-decisions" style={{position:'relative',width:'100%',height:'100%',background:'var(--osd-bg)',color:'var(--osd-text)',fontFamily:'var(--osd-font-body)'}}>
<h1 style={{position:'absolute',left:100,top:65,width:1720,fontSize:62,fontWeight:700,lineHeight:1.13,margin:0}}>Six assumptions tested</h1>
<div style={{position:'absolute',left:100,top:206,fontSize:27,fontWeight:700,color:'#676358'}}>THE ASSUMPTION</div>
<div style={{position:'absolute',left:860,top:206,fontSize:27,fontWeight:700,color:'#676358'}}>WHAT WE EXAMINED</div>
<Steps><Step><div style={{position:'absolute',left:100,top:262,width:1720,height:112,borderTop:'2px solid #CCC6B6'}}>
<p style={{position:'absolute',left:0,top:22,width:710,fontSize:34,lineHeight:1.25,margin:0,fontWeight:700}}>“I’ll just use a coding agent.”</p>
<p style={{position:'absolute',left:760,top:18,width:960,fontSize:34,lineHeight:1.25,margin:0,color:'#2E70FF',fontWeight:600}}>Same model, same task: what changed<br/>when we swapped the harness?</p>
</div></Step></Steps>
<Steps><Step><div style={{position:'absolute',left:100,top:378,width:1720,height:112,borderTop:'2px solid #CCC6B6'}}>
<p style={{position:'absolute',left:0,top:22,width:710,fontSize:34,lineHeight:1.25,margin:0,fontWeight:700}}>“More tools make a better agent.”</p>
<p style={{position:'absolute',left:760,top:18,width:960,fontSize:34,lineHeight:1.25,margin:0,color:'#2E70FF',fontWeight:600}}>Did another tool help—or add<br/>confusion, context, and cost?</p>
</div></Step></Steps>
<Steps><Step><div style={{position:'absolute',left:100,top:494,width:1720,height:112,borderTop:'2px solid #CCC6B6'}}>
<p style={{position:'absolute',left:0,top:22,width:710,fontSize:34,lineHeight:1.25,margin:0,fontWeight:700}}>“More instructions, skills, and memory help.”</p>
<p style={{position:'absolute',left:760,top:18,width:960,fontSize:34,lineHeight:1.25,margin:0,color:'#2E70FF',fontWeight:600}}>What helped to remember or retrieve?<br/>What became stale or unnecessary?</p>
</div></Step></Steps>
<Steps><Step><div style={{position:'absolute',left:100,top:610,width:1720,height:112,borderTop:'2px solid #CCC6B6'}}>
<p style={{position:'absolute',left:0,top:22,width:710,fontSize:34,lineHeight:1.25,margin:0,fontWeight:700}}>“Always use the strongest model.”</p>
<p style={{position:'absolute',left:760,top:18,width:960,fontSize:34,lineHeight:1.25,margin:0,color:'#2E70FF',fontWeight:600}}>Could a cheaper model pass the checks?<br/>What evidence justified escalation?</p>
</div></Step></Steps>
<Steps><Step><div style={{position:'absolute',left:100,top:726,width:1720,height:112,borderTop:'2px solid #CCC6B6'}}>
<p style={{position:'absolute',left:0,top:22,width:710,fontSize:34,lineHeight:1.25,margin:0,fontWeight:700}}>“Give it an objective and let it run.”</p>
<p style={{position:'absolute',left:760,top:18,width:960,fontSize:34,lineHeight:1.25,margin:0,color:'#2E70FF',fontWeight:600}}>Did it make progress?<br/>What evidence showed it was done?</p>
</div></Step></Steps>
<Steps><Step><div style={{position:'absolute',left:100,top:842,width:1720,height:112,borderTop:'2px solid #CCC6B6'}}>
<p style={{position:'absolute',left:0,top:22,width:710,fontSize:34,lineHeight:1.25,margin:0,fontWeight:700}}>“We need a multi-agent system.”</p>
<p style={{position:'absolute',left:760,top:18,width:960,fontSize:34,lineHeight:1.25,margin:0,color:'#2E70FF',fontWeight:600}}>Which tasks benefited enough to justify<br/>extra compute and coordination?</p>
</div></Step></Steps>
<div style={{position:'absolute',right:100,bottom:30,fontSize:25,color:'#999386'}}>@rajistics</div><svg data-robot-marker aria-hidden="true" viewBox="330 0 330 290" style={{position:'absolute',right:260,bottom:20,width:55,height:49,pointerEvents:'none'}}><image href={harnessRobot} width="1430" height="1070"/></svg></div>;

